import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, smoothstep, sub, mul } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root group (scene placement handled externally)
  const root = new Group();

  // ---------- BACKGROUND PLANE ----------
  const bgWidth = 7.0;
  const bgHeight = 0.35;
  const bgGeometry = new PlaneGeometry(bgWidth, bgHeight);
  const edgeFade = 0.6; // units
  const edgeNorm = edgeFade / bgWidth; // normalized UV width for fade

  const uvNode = uv();
  const leftFade = smoothstep(0, edgeNorm, uvNode.x);
  const rightFade = smoothstep(0, edgeNorm, sub(1, uvNode.x));
  const alphaNode = mul(leftFade, rightFade);

  const bgMaterial = new MeshBasicNodeMaterial({
    color: new Color('#111117'),
    transparent: true,
    alpha: alphaNode,
  });

  const bgMesh = new Mesh(bgGeometry, bgMaterial);
  bgMesh.position.z = 0;
  root.add(bgMesh);

  // ---------- HORIZONTAL HAIRLINES ----------
  const lineHeight = 0.006;
  const lineGeometry = new PlaneGeometry(bgWidth, lineHeight);
  const lineColor = new Color('#23232b');
  const lineMaterial = new MeshBasicNodeMaterial({ color: lineColor });

  const topLine = new Mesh(lineGeometry, lineMaterial);
  topLine.position.y = bgHeight / 2 - lineHeight / 2;
  topLine.position.z = 0.001;
  root.add(topLine);

  const bottomLine = new Mesh(lineGeometry, lineMaterial);
  bottomLine.position.y = -bgHeight / 2 + lineHeight / 2;
  bottomLine.position.z = 0.001;
  root.add(bottomLine);

  // ---------- TICKER STRIP ----------
  const stripGroup = new Group();
  const tickWidth = 0.02;
  const tickHeight = 0.14;
  const tickGeometry = new PlaneGeometry(tickWidth, tickHeight);
  const tickMaterial = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.5,
  });

  const textColor = '#e8ecf2';
  const fontSizePx = 13;
  const gap = 0.5; // 2 × base unit (base unit = 0.25)

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // layout variables
  let cursor = 0;

  for (const item of items) {
    // left gap before tick
    cursor += gap;

    // tick mark
    const tick = new Mesh(tickGeometry, tickMaterial);
    tick.position.set(cursor, 0, 0.02);
    stripGroup.add(tick);

    // right gap after tick
    cursor += gap;

    // text entry
    const textString = typeof item === 'string' ? item : item.text ?? '';
    const textMesh = ctx.fontAtlas.createText(textString, {
      fontSize: fontSizePx,
      color: textColor,
      align: 'left',
    });
    textMesh.position.set(cursor, 0, 0.02);
    stripGroup.add(textMesh);

    // advance cursor for next entry (approximate spacing)
    cursor += 3; // enough space for the next item
  }

  // total length of one strip
  const stripLength = cursor;

  // duplicate strip for seamless looping
  const stripDup = stripGroup.clone(true);
  stripDup.position.x = stripLength;
  const masterStrip = new Group();
  masterStrip.add(stripGroup);
  masterStrip.add(stripDup);
  root.add(masterStrip);

  // ---------- CINEMATIC PRIMITIVE ----------
  const flyPrimitive = ctx.primitives['fly-through'](masterStrip, {
    depthUnits: 0,
    speed: 0.4,
  });

  // ---------- USERDATA ----------
  root.userData.handlers = {};

  const disposables = [];

  // store material & geometry disposals
  disposables.push(() => {
    bgGeometry.dispose();
    bgMaterial.dispose();
    lineGeometry.dispose();
    lineMaterial.dispose();
    tickGeometry.dispose();
    tickMaterial.dispose();
  });

  // primitive cleanup
  disposables.push(() => {
    if (flyPrimitive && typeof flyPrimitive.cleanup === 'function') {
      flyPrimitive.cleanup();
    }
  });

  root.userData.cleanup = () => {
    // kill any GSAP timelines that might exist (none in this node, but safety)
    gsap.globalTimeline.clear();

    disposables.forEach((fn) => {
      try {
        fn();
      } catch (e) {
        // swallow cleanup errors
      }
    });
  };

  return root;
}
